    body: `# ITパスポート試験 当日の持ち物完全リスト

ITパスポート試験は CBT（Computer Based Testing）方式で実施されるため、紙の試験とは持ち物が大きく異なります。当日「これを忘れて受験できなかった」となれば、せっかくの学習時間が無駄になります。本記事では、CBT 会場で慌てないための持ち物リストと、当日の流れ・注意点を整理します。

> 本記事は 過去問AI が独自にまとめた学習ガイドです。試験要項の最新情報は必ず [IPA 公式ページ](https://www.ipa.go.jp/shiken/) で確認してください。

## 持ち物は最小限——CBT 試験室は手ぶら同然

CBT 方式の ITパスポートでは、私物のほぼすべてを会場のロッカーに預けます。試験室に持ち込めるのは原則として次の物だけです。

1. **本人確認書類**（写真付き公的書類）
2. **確認票**（マイページから印刷、またはスマホ画面提示）
3. **会場入館用のセキュリティカードや受付票**（会場による）

つまり、参考書・メモ帳・電卓・スマホ・自分の腕時計などはすべて持ち込めません。会場で支給される筆記用具とメモ用紙だけを使い、画面の問題に PC マウスで答えます。

## 本人確認書類として認められるもの

ITパスポートで本人確認書類として認められるのは、**顔写真付きの公的書類** が原則です。

- 運転免許証
- マイナンバーカード（通知カードは不可）
- 旅券（パスポート）
- 写真付き住民基本台帳カード
- 在留カード・特別永住者証明書（写真付き）
- 写真付き学生証（高校生以下の場合のみ補助書類として可の会場あり）

写真なしの健康保険証や学生証は単独では受理されないことが多く、その場合は健康保険証 + 学生証 + 公共料金領収書など、複数書類の組み合わせが必要になります。**事前に試験運営事務局へ問い合わせて確認** しておくのが鉄則です。

## 当日 NG な持ち込み品

CBT 試験室では次の物が一切持ち込めません。受付後にすべてロッカーへ預けます。

- スマートフォン・スマートウォッチ（電源を切っていても不可）
- 自分の腕時計（電卓機能の有無を問わない）
- 電卓
- 参考書・ノート・自分のメモ
- 飲食物
- 帽子・サングラス・マフラー

腕時計が使えないため、残り時間は会場の壁掛け時計または PC 画面上のタイマーで確認します。マウスの右上などにタイマーが常時表示されるので、操作には事前に慣れておきましょう。

## 当日の流れ

ITパスポート CBT 試験の当日は、次の流れで進みます。

1. **試験開始 30 分前**：会場到着、受付で本人確認書類と確認票を提示
2. **受付完了**：私物をロッカーに預け、試験室へ案内
3. **試験室入室**：PC・マウス・メモ用紙・鉛筆が用意されている
4. **試験開始**：120 分、100 問の四択問題
5. **試験終了**：途中退室も可能、即時に仮スコアが画面表示
6. **退室**：ロッカーから私物を回収、解散

仮スコアは IRT（項目応答理論）によるもので、正式な合否は約 1 ヶ月後の公式発表を待つ必要があります。

## 服装と試験室外で必要な物

CBT 試験室は会場によって室温が異なります。冷房・暖房が効きすぎている可能性を考慮し、**羽織れる上着** を持参すると安心です。試験中はコート・マフラーをロッカーに預けるため、薄手のカーディガンやセーターがおすすめです。

会場までの交通費や昼食代の現金、コンタクトレンズ用品、ハンカチ・ティッシュなどは試験室外で必要になるので別途用意しましょう。

## 受験票（確認票）を忘れたら？

確認票は紙印刷だけでなくスマホ画面表示でも受理される会場が増えています。前日に Wi-Fi 環境でマイページにログインし、画面表示できるか確認しておくと当日トラブルを避けられます。

ただし、**本人確認書類を忘れるとどんな事情でも受験できません**。受付で却下されればその日の受験料は戻ってきません。前日のうちにカバンに入れ、当日朝に再確認するクセを付けておきましょう。

## 試験前日にやっておく準備

前日の夜にやっておきたい準備：

- 確認票の印刷または画面確認
- 本人確認書類をカバンへ
- 会場までの経路と所要時間を確認
- 当日の服装を出しておく
- 22 時就寝で睡眠を確保

直前 1 週間の学習計画は [IPA試験 直前1週間でやるべきこと](/blog/ipa-cyokusen-1shukan) を、前日チェックリストは [IPA試験前日チェックリスト](/blog/shiken-zenjitsu-checklist) を併せて参照してください。

## CBT の操作に慣れる事前演習

紙試験と違い、CBT 試験では画面上で問題を読み、マウスで選択肢をクリックします。慣れていないと最初の数問で時間を浪費しがちです。事前に [ITパスポート 過去問](/ip) を PC ブラウザで 5 回以上演習し、画面操作と時間配分に慣れておくと当日のパフォーマンスが安定します。

## まとめ

- CBT 方式のため持ち込みは本人確認書類と確認票のみ
- 写真付き身分証以外は本人確認書類として受理されにくい
- スマホ・腕時計・電卓・参考書はすべて持ち込み不可
- 試験室の冷暖房に備えて羽織れる上着を持参
- 前日のうちに確認票・身分証・経路・服装を整える

## よくある質問

**Q. 健康保険証だけで受験できますか？**
原則として写真なしの健康保険証は単独では受理されません。学生は学生証 + 健康保険証の 2 点持参で対応可能な会場もありますが、必ず事前に試験運営事務局へ確認してください。

**Q. 試験中にトイレに行けますか？**
途中退室は可能ですが、再入室不可となる会場もあります。試験開始前に必ず会場ルールを確認し、開始前にトイレを済ませておくのが安全です。

**Q. CBT は何回でも受験できますか？**
ITパスポートは原則として年間に複数回受験可能ですが、同一会場・同一日の連続受験はできません。再受験には申込から数日のクーリング期間が必要な場合があります。

**Q. 体調不良で当日キャンセルしたい場合、受験料は戻りますか？**
原則として受験料の返金はありません。受験日の変更（リスケジュール）は受験予定日の前日までならマイページから可能です。当日キャンセルは欠席扱いとなります。

**Q. CBT 操作に自信がありません。練習方法はありますか？**
[ITパスポート 過去問](/ip) を PC ブラウザで解くだけで CBT 操作に近い感覚が身に付きます。マウス操作と画面読みのスピードを上げておくと、当日の時間配分が楽になります。
`,
