    description:
      "基本情報技術者試験の科目Bはアルゴリズムだけでなく情報セキュリティ分野からも出題されます。長文トレースより短く知識で取りやすいセキュリティ問題を確実な得点源にするための頻出テーマ・対策手順・AI活用法を解説します。",
