    body: `# 応用情報技術者は何点で合格？

「[応用情報技術者試験](/ap)は何点取れば合格なの？」「午前と午後は合算なの？」「午前がダメだと午後は採点されないって本当？」——合格ラインの仕組みは意外と誤解されがちです。本記事は **合格基準と採点の仕組み** を、IPA が公表している範囲で正確に整理します。

> 本記事は 過去問AI が独自にまとめた学習ガイドです。試験要項・採点方式の最新情報は必ず [IPA 公式ページ](https://www.ipa.go.jp/shiken/) で確認してください。

## 合格基準：午前・午後それぞれ100点満点中60点

応用情報技術者試験は **午前試験** と **午後試験** で構成され、合否は次の基準で判定されます。

- **午前試験**：100点満点・**基準点60点**
- **午後試験**：100点満点・**基準点60点**

合格には **午前・午後ともに60点以上** が必要です。**両方の得点を合算するのではなく、それぞれが60点以上** でなければなりません。片方だけ高得点でも、もう一方が60点未満なら不合格になります。

## 基本情報（IRT）とは採点方式が違う

ここを混同する受験者が多いポイントです。基本情報技術者（FE）は **IRT（項目応答理論）** で1000点満点・600点基準という独特な採点ですが、**応用情報は素点方式**で、100点満点中60点という分かりやすい基準です。

- 応用情報は「正答・配点の積み上げ」で素点が決まる（午前は1問の配点が公表され、80問で100点に按分）
- 「何割で合格か」がそのまま **6割（60点）** に対応する、シンプルな構造
- 基本情報の「正答率6割でも合格とは限らない」という IRT 特有の不安は、応用情報には当てはまらない

基本情報側の IRT・1000点満点の仕組みが気になる人は、[基本情報技術者は何点で合格？（科目A・科目BとIRT）](/blog/fe-goukaku-ten-irt) で詳しく整理しています。

## 午前が60点未満だと午後は採点されない（多段階選抜方式）

応用情報技術者試験は **多段階選抜方式** を採用しています。

- **午前試験の得点が基準点（60点）に達しなかった場合、午後試験は採点されず不合格** になります
- つまり、午後でどれだけ良い答案を書いても、午前を突破していなければ得点として評価されません

午前は過去問の再出題が多く対策しやすい一方、ここを軽視すると午後の努力がまるごと無駄になります。**まず午前で確実に60点を超える** ことが、合格戦略の大前提です。

## 午前・午後の試験形式

| 区分 | 試験時間 | 出題形式 | 出題数・解答数 |
| --- | --- | --- | --- |
| 午前 | 150分 | 多肢選択式（四肢択一） | 80問・80問解答 |
| 午後 | 150分 | 記述式 | 11問・5問解答（情報セキュリティ必答＋4問選択） |

午前は知識の四択、午後は長文を読んで記述で答える試験で、**問われる力がまったく異なります**。

## では何点を目標に勉強すればいいか

基準が「各60点」と明確な分、戦略はシンプルです。

- **午前**：過去問の再出題が多いため、過去問演習で安定して **80%以上** を取れる状態を作れば、本番で60点を割るリスクはほぼ消えます
- **午後**：選択した分野で **記述の部分点を確実に積む**。満点を狙うより「6割を堅実に超える」答案づくりが現実的です
- 午前で余裕を作り、午後は時間配分で取りこぼさない——これが60点×2をクリアする最短ルートです

## 午後で確実に60点を取るには

合否を分けやすいのは、配点の重い記述問題が並ぶ **午後** です。応用情報の午後は11分野から5問（情報セキュリティ必答＋4問選択）を解きます。どの分野を選ぶかで得点は大きく変わるため、選択戦略は [応用情報技術者 午後選択戦略](/blog/ap-gogo-sentaku) で、150分の時間配分は [応用情報 午後で時間が足りない人へ](/blog/ap-gogo-jikan-haibun) で詳しく扱っています。

実際の問題で手を動かすなら、[応用情報技術者の過去問](/ap) を解き、記述で詰まったら AI コパイロットに「この設問の採点ポイントを列挙して」「私の解答の不足点を指摘して」と聞けば、その場で答案の精度を上げられます。

## まとめ

- 合格には **午前・午後ともに60点以上（各100点満点）** が必要で、合算ではなく科目ごとの判定
- 応用情報は **素点方式**で、基本情報の IRT（1000点満点）とは採点の仕組みが違う
- **多段階選抜方式**のため、午前が60点未満だと午後は採点されず不合格
- まず午前で確実に60点を超え、午後は記述の部分点を堅実に積む

## よくある質問

**Q. 応用情報技術者は何点で合格ですか？**
午前・午後それぞれ100点満点中60点以上が必要です。両方が基準点を満たして初めて合格となり、片方だけ高得点でも不合格になります。

**Q. 午前と午後の点数は合算されますか？**
いいえ。合否は時間区分ごとに判定され、午前・午後それぞれが60点以上である必要があります。合算して120点あっても、片方が60点未満なら不合格です。

**Q. 午前がダメだと午後は採点されないというのは本当ですか？**
本当です。応用情報技術者試験は多段階選抜方式で、午前試験の得点が基準点（60点）に達しなかった場合、午後試験は採点されず不合格になります。まず午前を確実に突破することが前提です。

**Q. 基本情報のように正答率6割でも落ちることはありますか？**
応用情報は基本情報のような IRT（項目応答理論）ではなく素点方式のため、「6割正解＝60点」が基本的に対応します。基本情報特有の「正答率6割でも合格とは限らない」という不安は、応用情報には当てはまりません。
`,
