  general.push({
    slug: "ipa-goukaku-tsuchi-jiki",
    title: "IPA情報処理試験 合格発表と合格証書の発送時期｜結果通知までのスケジュール",
    description:
      "IPA情報処理技術者試験の合格発表・合格証書発送までのスケジュールを、春期・秋期・CBT試験別に整理。結果通知後の手続きと履歴書への記載タイミングも解説します。",
    tags: ["合格発表", "合格証書", "試験後", "結果通知"],
    publishedAt: publishedAtFor(longtail2Offset + 4),
    body: `# IPA情報処理試験 合格発表と合格証書の発送時期

「試験は終わったけれど、合格発表はいつ？合格証書はいつ届く？」——本試験を終えた受験者から最も多く寄せられる質問です。本記事では、IPA 情報処理技術者試験の結果通知から合格証書発送までのスケジュールを、春期・秋期・CBT 試験別に整理します。

> 本記事は 過去問AI が独自にまとめた学習ガイドです。試験要項の最新情報は必ず [IPA 公式ページ](https://www.ipa.go.jp/shiken/) で確認してください。

## 全体スケジュールの概要

PBT（紙試験）の試験では、本試験から合格発表までの期間は概ね **約 2 ヶ月** です。合格証書（合格通知書）の発送はさらに後で、本試験から **約 2.5〜3 ヶ月後** が目安となります。

CBT 試験（IP・SG）はもっと早く、本試験当日に仮スコアが表示され、約 1 ヶ月後に正式な合格発表が行われます。

## 春期試験のスケジュール例

春期試験（4 月実施）の場合、典型的なスケジュールは次の通りです。

- **4 月中旬**：本試験実施
- **5 月上旬**：解答例公開（IPA 公式ページ）
- **6 月下旬〜7 月初旬**：合格発表（IPA マイページで合否確認）
- **7 月中旬〜下旬**：合格証書の発送

春期は受験者数が比較的多いため、合格発表から証書到着まで 2〜3 週間かかることが一般的です。

## 秋期試験のスケジュール例

秋期試験（10 月実施）の場合：

- **10 月中旬**：本試験実施
- **11 月上旬**：解答例公開
- **12 月下旬〜1 月初旬**：合格発表
- **1 月中旬〜下旬**：合格証書の発送

年末年始を挟むため、合格発表後の証書発送がやや遅くなる傾向があります。

## CBT 試験（IP・SG）のスケジュール

ITパスポート（IP）・情報セキュリティマネジメント（SG）は通年 CBT 方式です。

- **試験当日**：終了直後に画面で仮スコア表示（IRT による）
- **試験翌月の中旬**：マイページで正式な合否確認
- **合格発表後 1〜2 ヶ月**：合格証書発送

仮スコアと正式合否は通常一致しますが、稀に IRT 換算のブレで結果が変わることがあります。仮スコアで合格水準を超えていても、油断せず正式発表を待つのが安全です。

## 合格発表当日にすること

合格発表当日は、IPA の **受験者用マイページ** にログインして合否を確認します。受験番号と生年月日が必要です。発表時刻は通常 **正午（12:00）** ですが、アクセス集中でつながりにくくなることがあるため、午後にずらすのも一案です。

合格していた場合、マイページから次の情報が確認できます。

- 試験区分・受験番号
- 合格証書番号
- 午前 I・午前 II・午後 I・午後 II の各得点
- 合格証書発送予定日

## 合格証書の郵送方法

合格証書は **普通郵便** で発送されます。書留や速達ではないため、受験票で登録した住所のポストに直接届きます。

- 引っ越し直後で住所変更が間に合わなかった場合、転居届を郵便局に出していれば 1 年間転送
- 万が一紛失した場合、IPA から再発行は可能（手数料 + 申請手続必要）

紛失防止のため、届いたらすぐ写真撮影・スキャンしてデジタル保管しておくと安心です。

## 合格証書到着前に履歴書へ書けるか

転職・就活の場面で「合格証書はまだ届いていないが、合格発表は確認済み」というケースは頻発します。結論として、**合格発表日以降は履歴書に記載可能** です。

履歴書には次の形式で記載するのが一般的です。

- 「YYYY 年 X 月　情報処理技術者試験　応用情報技術者試験合格」

合格証書番号まで記載する必要はありません。面接で証書原本の提示を求められた場合に備えて、合格証書はファイルに保管しておきましょう。詳細は [IT資格を履歴書に書く正しい形式](/blog/it-shikaku-rirekisho-kakikata) を参照してください。

## 合格発表直後にやっておくこと

合格直後は次の手続きをやっておくと安心です。

1. **マイページのスクリーンショット保存**：合格証書番号と得点入りで保存
2. **会社への合格報告**：資格手当・報奨金制度がある場合、申請に必要
3. **次の試験の検討**：応用情報合格者は午前 I 免除が 2 年間有効

応用情報合格後の次の挑戦先選びは [IPA資格取得後のキャリアパス](/blog/shikaku-career-path) で解説しています。

## 合格証書が届かない場合の対処

合格発表から 1 ヶ月以上経っても証書が届かない場合は、IPA に問い合わせます。

- 住所変更を申請していたか確認
- 郵便局に転送届を出していたか確認
- 同居家族の誰かが受け取って忘れていないか確認

それでも届かない場合は IPA に再発行を申請します。手数料が発生するため、住所変更は申込時に必ず正しく入力しましょう。

## 不合格でも諦めないために

不合格だった場合、IPA マイページに「不合格」と表示されますが、得点も併せて開示されます。あと何点足りなかったかが分かるため、次回の学習計画に活かせます。不合格からのリカバリーは [IPA試験に落ちた後の3ヶ月リカバリープラン](/blog/ipa-shiken-fugoukaku-kara-no-recovery) を参照してください。

## まとめ

- PBT 試験：合格発表は本試験から約 2 ヶ月後、証書は 2.5〜3 ヶ月後
- CBT 試験：仮スコアは試験当日、正式発表は翌月中旬
- 合格証書は普通郵便で届く、紛失時は再発行可能
- 合格発表日以降は履歴書に記載可能
- 不合格時も得点が開示されるため次回計画に活用

## よくある質問

**Q. 合格発表の時刻は何時ですか？**
通常は正午（12:00）です。アクセス集中で繋がりにくい場合は、午後にずらしてアクセスするのがおすすめです。

**Q. 合格証書を紛失した場合、再発行できますか？**
できます。IPA に申請すれば手数料を支払って再発行可能です。

**Q. 合格証書が届く前に転職活動を始めて大丈夫ですか？**
合格発表日以降は履歴書に記載可能なため、転職活動を始めて問題ありません。マイページのスクリーンショットがあれば、面接で提示できます。

**Q. 合格証書はメールで送られてきますか？**
PDF 形式の通知は受験者用マイページからダウンロードできますが、紙の合格証書は普通郵便で送られます。

**Q. 試験日から 3 ヶ月以上経っても証書が届きません。**
住所変更や郵便事故の可能性があります。まずマイページで発送日を確認し、IPA に問い合わせてください。
`,
    relatedSlugs: ["ipa-shiken-moushikomi-nagare", "shikaku-career-path", "ipa-shiken-fugoukaku-kara-no-recovery"],
  });

